1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type Result = { premium: number } | { payout: number; remainingCap: number };
25	
26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
28	const CURSE_SURCHARGE_RATE = 0.5;
29	const HIGH_ENCHANTMENT_THRESHOLD = 5;
30	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
31	const LOYALTY_YEARS_THRESHOLD = 2;
32	const LOYALTY_DISCOUNT_RATE = 0.2;
33	
34	const BASE_PREMIUMS: Record<string, number> = {
35	  sword: 100,
36	  amulet: 60,
37	  staff: 80,
38	  potion: 40,
39	  rune: 25,
40	  moonstone: 25,
41	};
42	
43	const BLOCK_SIZE = 3;
44	const BLOCK_PREMIUM = 60;
45	
46	/** Items that share the same `type`, and so are priced together. */
47	type AlikeItems = Item[];
48	
49	const groupByType = (items: Item[]): AlikeItems[] => {
50	  const distinctTypes = [...new Set(items.map((item) => item.type))];
51	  return distinctTypes.map((type) => items.filter((item) => item.type === type));
52	};
53	
54	const formsBlock = (items: AlikeItems): boolean => items.length === BLOCK_SIZE;
55	
56	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
57	
58	const groupBasePremium = (alikeItems: AlikeItems): number =>
59	  formsBlock(alikeItems)
60	    ? BLOCK_PREMIUM
61	    : alikeItems.reduce((total, item) => total + itemBasePremium(item), 0);
62	
63	const totalBasePremium = (items: Item[]): number =>
64	  groupByType(items).reduce((total, alikeItems) => total + groupBasePremium(alikeItems), 0);
65	
66	const isCursed = (item: Item): boolean => item.cursed === true;
67	
68	const isHighlyEnchanted = (item: Item): boolean =>
69	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
70	
71	/**
72	 * An item-specific surcharge: `rate` × the item's own base premium, charged
73	 * once per item the rule `applies` to. Never charged on the policy's base, so
74	 * every rule contributes an independent additive term.
75	 */
76	type ItemSurcharge = { applies: (item: Item) => boolean; rate: number };
77	
78	const ITEM_SURCHARGES: ItemSurcharge[] = [
79	  { applies: isCursed, rate: CURSE_SURCHARGE_RATE },
80	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
81	];
82	
83	const itemSurchargesFor = (item: Item): number =>
84	  ITEM_SURCHARGES.filter(({ applies }) => applies(item)).reduce(
85	    (total, { rate }) => total + itemBasePremium(item) * rate,
86	    0,
87	  );
88	
89	const totalItemSurcharges = (items: Item[]): number =>
90	  items.reduce((total, item) => total + itemSurchargesFor(item), 0);
91	
92	/**
93	 * A policy-wide modifier: `rate` × the policy's base premium, charged once per
94	 * quote. Like the item surcharges, each rule contributes an independent
95	 * additive term rather than compounding on earlier ones — so a discount is just
96	 * a negative `rate`, not a subtraction applied at some point in a sequence.
97	 */
98	type PolicyRate = { applies: (policy: Policy) => boolean; rate: number };
99	
100	/** Everything a policy-wide rule may look at when deciding whether it applies. */
101	type Policy = { customer: Customer };
102	
103	const always = (): boolean => true;
104	
105	const isLoyalCustomer = ({ customer }: Policy): boolean =>
106	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
107	
108	const POLICY_RATES: PolicyRate[] = [
109	  { applies: always, rate: FIRST_INSURANCE_SURCHARGE_RATE },
110	  { applies: isLoyalCustomer, rate: -LOYALTY_DISCOUNT_RATE },
111	];
112	
113	const totalPolicyAdjustments = (base: number, policy: Policy): number =>
114	  POLICY_RATES.filter(({ applies }) => applies(policy)).reduce(
115	    (total, { rate }) => total + base * rate,
116	    0,
117	  );
118	
119	const quotePremium = (items: Item[], policy: Policy): number => {
120	  const base = totalBasePremium(items);
121	  // Every term is added to `base`, never multiplied onto a running total. The
122	  // algebraically equivalent base * (1 + rate) yields 110.00000000000001 for
123	  // base 100, which Math.ceil turns into a premium that is 1 G too high.
124	  return Math.ceil(
125	    base + totalItemSurcharges(items) + totalPolicyAdjustments(base, policy) + PROCESSING_FEE,
126	  );
127	};
128	
129	export const runScenario = (scenario: Scenario): Result[] =>
130	  scenario.steps.map((step) => {
131	    if (step.op === "quote")
132	      return { premium: quotePremium(step.items, { customer: scenario.customer }) };
133	    throw new Error(`Unsupported step: ${step.op}`);
134	  });
